#include <iostream>
#include <vector>
#include <cmath>

class Polynomial {
    std::vector<double> coeffs; // coeffs[i] is coefficient of x^i

    void trim() {
        while (coeffs.size() > 1 && coeffs.back() == 0.0) {
            coeffs.pop_back();
        }
    }

public:
    Polynomial() : coeffs(1, 0.0) {}
    explicit Polynomial(std::vector<double> c) : coeffs(std::move(c)) {
        if (coeffs.empty()) coeffs.push_back(0.0);
        trim();
    }

    // Unary minus
    Polynomial operator-() const {
        Polynomial res = *this;
        for (double &val : res.coeffs) {
            val = -val;
        }
        return res;
    }

    // Binary addition
    friend Polynomial operator+(const Polynomial &a, const Polynomial &b) {
        std::size_t sz = std::max(a.coeffs.size(), b.coeffs.size());
        std::vector<double> res(sz, 0.0);
        for (std::size_t i = 0; i < sz; ++i) {
            if (i < a.coeffs.size()) res[i] += a.coeffs[i];
            if (i < b.coeffs.size()) res[i] += b.coeffs[i];
        }
        return Polynomial(res);
    }

    // Binary subtraction
    friend Polynomial operator-(const Polynomial &a, const Polynomial &b) {
        return a + (-b);
    }

    // Binary multiplication
    friend Polynomial operator*(const Polynomial &a, const Polynomial &b) {
        std::size_t sz = a.coeffs.size() + b.coeffs.size() - 1;
        std::vector<double> res(sz, 0.0);
        for (std::size_t i = 0; i < a.coeffs.size(); ++i) {
            for (std::size_t j = 0; j < b.coeffs.size(); ++j) {
                res[i + j] += a.coeffs[i] * b.coeffs[j];
            }
        }
        return Polynomial(res);
    }

    // Evaluation at x using Horner's method
    double operator^(double x) const {
        double val = 0.0;
        for (auto it = coeffs.rbegin(); it != coeffs.rend(); ++it) {
            val = val * x + *it;
        }
        return val;
    }

    // Stream operators
    friend std::istream &operator>>(std::istream &is, Polynomial &p) {
        int deg;
        if (!(is >> deg)) return is;
        p.coeffs.assign(deg + 1, 0.0);
        for (int i = 0; i <= deg; ++i) {
            is >> p.coeffs[i];
        }
        p.trim();
        return is;
    }

    friend std::ostream &operator<<(std::ostream &os, const Polynomial &p) {
        bool first = true;
        for (int i = static_cast<int>(p.coeffs.size()) - 1; i >= 0; --i) {
            double c = p.coeffs[i];
            if (c == 0.0 && p.coeffs.size() > 1) continue;
            if (!first && c > 0) os << " + ";
            else if (!first && c < 0) { os << " - "; c = -c; }
            else if (first && c < 0) { os << "-"; c = -c; }
            os << c;
            if (i == 1) os << "x";
            else if (i > 1) os << "x^" << i;
            first = false;
        }
        return os;
    }
};

int main() {
    Polynomial p, q, r, s;
    double x;
    if (std::cin >> p >> q >> r >> s >> x) {
        Polynomial f = -(p + q) * (r - s);
        double g = f ^ x;
        std::cout << "Da thuc f: " << f << "\n";
        std::cout << "x = " << x << "\n";
        std::cout << "f(x) = " << g << "\n";
    }
    return 0;
}
